import {
  integer,
  pgTable,
  timestamp,
  uniqueIndex,
  uuid,
  varchar,
} from 'drizzle-orm/pg-core';
import { users } from './users.schema';

/**
 * One browser/device an account has successfully logged in from.
 *
 * The id is generated by the browser and persisted there; this table only
 * remembers which ids an account has used, so a later login from an unseen id
 * can raise the `security.new_login` notification. It is a registry, not an
 * audit log — the notification row (and its `createdAt`) is the historical
 * record. `lastSeenAt` is refreshed on login, on token refresh and when the
 * settings page reads the list.
 *
 * `sessionId` is the revocation epoch: tokens carry it as `sid`, and revoking a
 * device rotates it, so every token minted before the revoke stops matching.
 * It is deliberately NOT rotated on login — a re-login on the same browser
 * reuses the row's current value.
 *
 * The FK cascades: `AccountPurgeService` hard-deletes `users` rows and relies
 * on every FK into `users` taking its rows along.
 */
export const userLoginDevices = pgTable(
  'user_login_devices',
  {
    id: uuid('id').defaultRandom().primaryKey(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    /** Browser-generated; validated by `readClientDevice` before it lands here. */
    deviceId: varchar('device_id', { length: 128 }).notNull(),
    /** Friendly label, e.g. "Chrome on Linux"; null when the client sent none. */
    deviceName: varchar('device_name', { length: 120 }),
    /** `browser` or `app`; null for clients that send no rich info. */
    clientType: varchar('client_type', { length: 16 }),
    browserName: varchar('browser_name', { length: 40 }),
    browserVersion: varchar('browser_version', { length: 40 }),
    osName: varchar('os_name', { length: 40 }),
    osVersion: varchar('os_version', { length: 40 }),
    /** Android UA model, "iPhone"/"iPad", or an app-supplied model. */
    deviceModel: varchar('device_model', { length: 80 }),
    /** Web/app build stamp (`YYYY.MM.DD`). */
    clientVersion: varchar('client_version', { length: 40 }),
    /** Raw UA for browser sessions, kept so parsing can improve later. */
    userAgent: varchar('user_agent', { length: 512 }),
    /** Revocation epoch; goes into the JWT as `sid`. Rotates only on revoke. */
    sessionId: uuid('session_id').defaultRandom().notNull(),
    /**
     * Refresh-token family generation, carried as `gen`. Bumped on every
     * rotation, so a token minted before the bump is stale: presenting one is
     * either a lost race (inside `REFRESH_REUSE_GRACE_SECONDS`) or a replay,
     * and a replay revokes the whole family.
     */
    refreshEpoch: integer('refresh_epoch').default(0).notNull(),
    /** When the epoch last changed; anchors the grace window above. */
    refreshRotatedAt: timestamp('refresh_rotated_at', { withTimezone: true }),
    revokedAt: timestamp('revoked_at', { withTimezone: true }),
    firstSeenAt: timestamp('first_seen_at', { withTimezone: true })
      .defaultNow()
      .notNull(),
    lastSeenAt: timestamp('last_seen_at', { withTimezone: true })
      .defaultNow()
      .notNull(),
  },
  (t) => [
    // Also serves the per-user lookup the login path runs.
    uniqueIndex('user_login_devices_user_device_uq').on(t.userId, t.deviceId),
    // The per-request guard lookup: user + revocation epoch.
    uniqueIndex('user_login_devices_user_session_uq').on(t.userId, t.sessionId),
  ],
);

export type UserLoginDeviceRow = typeof userLoginDevices.$inferSelect;
export type NewUserLoginDevice = typeof userLoginDevices.$inferInsert;
